        {
          "name": "cached_url",
          "type": "VARCHAR",
          "description": "Path to the cached image file"
        },
        {
          "name": "image_hash",
          "type": "VARCHAR",
          "description": "Hash of the image for integrity verification"
        },
        {
          "name": "last_hash_check",
          "type": "DATE",
          "description": "Date of the last hash check"
        },
        {
          "name": "image_format",
